  orgId: OrgId,
  fromSlug: string,
  toSlug: string,
): Promise<Organization> {
  const stamp = toIsoTimestamp(new Date());

  getDb()
    .delete(organizationSlugHistory)
    .where(and(eq(organizationSlugHistory.orgId, orgId), eq(organizationSlugHistory.slug, toSlug)))
    .run();

  getDb()
    .insert(organizationSlugHistory)
    .values({ id: newId(), orgId, slug: fromSlug, retiredAt: stamp })
    .run();

  const row = getDb()
    .update(organizations)
    .set({ slug: toSlug, updatedAt: stamp })
    .where(eq(organizations.id, orgId))
    .returning()
    .get();

  if (!row) throw new Error(`Organization ${orgId} not found`);
  return toOrganization(row);
}

