/**
 * Changes the workspace's URL. The new slug is a deliberate choice, not a
 * derivation: an unavailable slug is refused rather than suffixed. Renaming
 * to the current slug is a no-op — nothing changes and nothing publishes.
 * Otherwise the old slug is retired (see `ORG_SLUG_HOLD_DAYS`) rather than
 * released, and `organization.slug_changed` fires once.
 */
export async function renameOrganizationSlug(
  actor: Actor,
  input: RenameOrganizationSlugInput,
): Promise<Organization> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "org:update", orgResource(input.orgId));

  const org = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );

  if (org.slug === input.slug) {
    return org;
  }

  assertValidSlug(input.slug);

  const available = await orgRepo.isSlugAvailableForRename(input.slug, org.id);
  if (!available) {
    throw new InvalidSlugError(input.slug, "is already taken");
  }

  const updated = await orgRepo.renameOrgSlug(org.id, org.slug, input.slug);

  await emit("organization.slug_changed", {
    ...actorEnvelope(actor),
    from: org.slug,
    to: input.slug,
  });

  return updated;
}

