/**
 * Organization rows plus slug uniqueness lookups.
 *
 * Must call (do not reimplement): archivePatch, uniqueSlug
 */
import { and, eq, isNull, like, ne } from "drizzle-orm";
import { ORG_SLUG_HOLD_DAYS } from "@/config/constants";
import { newId } from "@/lib/id";
import { uniqueSlug } from "@/lib/slug";
import { archivePatch } from "@/lib/soft-delete";
import { getDb, organizationSlugHistory, members, organizations } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { toOrganization } from "./_mappers";
import type {
  CreateOrganizationInput,
  UpdateOrganizationInput,
} from "@/schemas/organization";
import type { OrgId, UserId } from "@/types/common";
import type { Organization } from "@/types/organization";

const MS_PER_DAY = 24 * 60 * 60 * 1000;

/** The instant on or after which a retirement that started then has released. */
function holdCutoffIso(now: Date = new Date()): string {
  return new Date(now.getTime() - ORG_SLUG_HOLD_DAYS * MS_PER_DAY).toISOString();
}

/** True while a slug retired at `retiredAt` is still inside its hold window. */
function isWithinHold(retiredAt: string, now: Date = new Date()): boolean {
  return retiredAt > holdCutoffIso(now);
}

export async function findOrgById(orgId: OrgId): Promise<Organization | null> {
  const row = getDb()
    .select()
    .from(organizations)
    .where(eq(organizations.id, orgId))
    .get();
  return row ? toOrganization(row) : null;
}

/**
 * Resolves a slug to its workspace the one way every caller must: the current
 * slug column first, and — while it is still on hold — a slug the workspace
 * retired by renaming away from it. This is the only lookup the session layer
 * and every other slug-based lookup may use; duplicating the retired-slug
 * fallback elsewhere would let the two drift.
 */
export async function findOrgBySlug(slug: string): Promise<Organization | null> {
  const direct = getDb()
    .select()
    .from(organizations)
    .where(and(eq(organizations.slug, slug), isNull(organizations.archivedAt)))
    .get();
  if (direct) return toOrganization(direct);

  const retirement = getDb()
    .select({ orgId: organizationSlugHistory.orgId, retiredAt: organizationSlugHistory.retiredAt })
    .from(organizationSlugHistory)
    .where(eq(organizationSlugHistory.slug, slug))
    .get();
  if (!retirement || !isWithinHold(retirement.retiredAt)) return null;

  const held = getDb()
    .select()
    .from(organizations)
    .where(and(eq(organizations.id, retirement.orgId), isNull(organizations.archivedAt)))
    .get();
  return held ? toOrganization(held) : null;
}

/**
 * Whether `slug` may become `orgId`'s slug: free of any other workspace's
 * current slug (live or archived) and free of any other workspace's still-held
 * retirement. A workspace's own retirement of `slug` never blocks it.
 */
export async function isSlugAvailableForRename(
  slug: string,
  orgId: OrgId,
): Promise<boolean> {
  const claimedByAnother = getDb()
    .select({ id: organizations.id })
    .from(organizations)
    .where(and(eq(organizations.slug, slug), ne(organizations.id, orgId)))
    .get();
  if (claimedByAnother) return false;

  const retirement = getDb()
    .select({ orgId: organizationSlugHistory.orgId, retiredAt: organizationSlugHistory.retiredAt })
    .from(organizationSlugHistory)
    .where(eq(organizationSlugHistory.slug, slug))
    .get();
  if (retirement && retirement.orgId !== orgId && isWithinHold(retirement.retiredAt)) {
    return false;
  }

  return true;
}

/**
 * Applies a slug rename: ends the workspace's own retirement of `toSlug` if it
 * holds one (renaming back to a slug it previously left), retires `fromSlug`
 * on its behalf, and writes the new current slug. Callers must have already
 * checked `isSlugAvailableForRename`.
 */
export async function renameOrgSlug(
  orgId: OrgId,
  fromSlug: string,
  toSlug: string,
): Promise<Organization> {
  const stamp = toIsoTimestamp(new Date());

  getDb()
    .delete(organizationSlugHistory)
    .where(and(eq(organizationSlugHistory.orgId, orgId), eq(organizationSlugHistory.slug, toSlug)))
    .run();

  getDb()
    .insert(organizationSlugHistory)
    .values({ id: newId(), orgId, slug: fromSlug, retiredAt: stamp })
    .run();

  const row = getDb()
    .update(organizations)
    .set({ slug: toSlug, updatedAt: stamp })
    .where(eq(organizations.id, orgId))
    .returning()
    .get();

  if (!row) throw new Error(`Organization ${orgId} not found`);
  return toOrganization(row);
}

/** Every org the user still holds a live membership in. */
export async function listOrgsForUser(
  userId: UserId,
): Promise<readonly Organization[]> {
  const rows = getDb()
    .select({ org: organizations })
    .from(members)
    .innerJoin(organizations, eq(organizations.id, members.orgId))
    .where(
      and(
        eq(members.userId, userId),
        isNull(members.archivedAt),
        isNull(organizations.archivedAt),
      ),
    )
    .all();

  return rows.map((row) => toOrganization(row.org));
}

/**
 * Creates the org row. The slug is de-duplicated here rather than in the
 * service so a race on the unique index still resolves to a usable slug.
 */
export async function insertOrg(
  input: CreateOrganizationInput,
  ownerId: UserId,
): Promise<Organization> {
  const taken = await listTakenOrgSlugs(input.slug);
  const slug = uniqueSlug(input.slug, taken);
  const stamp = toIsoTimestamp(new Date());

  const row = getDb()
    .insert(organizations)
    .values({
      id: newId(),
      name: input.name,
      slug,
      ownerId,
      plan: input.plan,
      logoUrl: null,
      trialEndsAt: null,
      createdAt: stamp,
      updatedAt: stamp,
    })
    .returning()
    .get();

  return toOrganization(row);
}

/**
 * Settings and profile patch. `slug` is accepted for the "change workspace
 * URL" form: the form validates the slug with `slugSchema` before it gets
 * here, so the column is written as given.
 */
export async function updateOrg(
  orgId: OrgId,
  patch: UpdateOrganizationInput & { readonly slug?: string },
): Promise<Organization> {
  const current = await findOrgById(orgId);
  if (!current) throw new Error(`Organization ${orgId} not found`);

  const settings = { ...current.settings, ...(patch.settings ?? {}) };

  const row = getDb()
    .update(organizations)
    .set({
      ...(patch.name === undefined ? {} : { name: patch.name }),
      ...(patch.slug === undefined ? {} : { slug: patch.slug }),
      ...(patch.logoUrl === undefined ? {} : { logoUrl: patch.logoUrl }),
      defaultIssueStatus: settings.defaultIssueStatus,
      allowPublicProjects: settings.allowPublicProjects,
      requireTwoFactor: settings.requireTwoFactor,
      digestHourUtc: settings.digestHourUtc,
      enabledFlagOverrides: JSON.stringify(settings.enabledFlagOverrides),
      updatedAt: toIsoTimestamp(new Date()),
    })
    .where(eq(organizations.id, orgId))
    .returning()
    .get();

  return toOrganization(row);
}

export async function archiveOrg(orgId: OrgId): Promise<Organization> {
  const row = getDb()
    .update(organizations)
    .set(archivePatch())
    .where(eq(organizations.id, orgId))
    .returning()
    .get();

  if (!row) throw new Error(`Organization ${orgId} not found`);
  return toOrganization(row);
}

/**
 * Feeds `uniqueSlug()`; matching on the prefix keeps the scan small. Includes
 * every workspace's current slug plus any slug still held by a retirement, so
 * a fresh signup is suffixed away from a slug that is mid-hold rather than
 * colliding with it.
 */
export async function listTakenOrgSlugs(
  prefix: string,
): Promise<readonly string[]> {
  const current = getDb()
    .select({ slug: organizations.slug })
    .from(organizations)
    .where(like(organizations.slug, `${prefix}%`))
    .all();

  const retired = getDb()
    .select({ slug: organizationSlugHistory.slug, retiredAt: organizationSlugHistory.retiredAt })
    .from(organizationSlugHistory)
    .where(like(organizationSlugHistory.slug, `${prefix}%`))
    .all();

  const held = retired
    .filter((row) => isWithinHold(row.retiredAt))
    .map((row) => row.slug);

  return [...new Set([...current.map((row) => row.slug), ...held])];
}

