cd "/private/var/folders/82/dclbn8z5181_3ppfdtp8csd40000gn/T/bench-scratch/4dce937c-9eba-42b7-bdfe-afd6586f0b3f" && cat > /tmp/rename-check.test.ts << 'EOF'
import { afterAll, beforeAll, describe, expect, it } from "vitest";
import { subscribe } from "@/lib/event-bus";
import { createTenant, useTemporaryDatabase } from "../tests/server/_support/fixtures";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as orgService from "@/server/services/organization-service";
import { InvalidSlugError } from "@/lib/slug";
import type { Tenant } from "../tests/server/_support/fixtures";

let cleanup: () => void;
let acme: Tenant;
let other: Tenant;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  acme = await createTenant("acme");
  other = await createTenant("other");
});

afterAll(() => cleanup());

describe("rename slug lifecycle", () => {
  it("no-op rename publishes nothing and changes nothing", async () => {
    const seen: unknown[] = [];
    const off = subscribe("organization.slug_changed", (p) => seen.push(p));
    const result = await orgService.renameOrganizationSlug(acme.actors.admin, {
      orgId: acme.org.id,
      slug: "acme",
    });
    expect(result.slug).toBe("acme");
    expect(seen).toHaveLength(0);
    off();
  });

  it("renames, retires old slug, resolves both old and new", async () => {
    const seen: any[] = [];
    const off = subscribe("organization.slug_changed", (p) => seen.push(p));
    const result = await orgService.renameOrganizationSlug(acme.actors.admin, {
      orgId: acme.org.id,
      slug: "acme-renamed",
    });
    expect(result.slug).toBe("acme-renamed");
    expect(seen).toHaveLength(1);
    expect(seen[0]).toMatchObject({ from: "acme", to: "acme-renamed", orgId: acme.org.id });
    off();

    const byNew = await orgRepo.findOrgBySlug("acme-renamed");
    expect(byNew?.id).toBe(acme.org.id);

    const byOld = await orgRepo.findOrgBySlug("acme");
    expect(byOld?.id).toBe(acme.org.id);
  });

  it("refuses a rename to a slug another org currently holds", async () => {
    await expect(
      orgService.renameOrganizationSlug(acme.actors.admin, {
        orgId: acme.org.id,
        slug: "other",
      }),
    ).rejects.toBeInstanceOf(InvalidSlugError);
  });

  it("refuses a rename to a slug another org has retired and still holds", async () => {
    await orgService.renameOrganizationSlug(other.actors.admin, {
      orgId: other.org.id,
      slug: "other-renamed",
    });
    // "other" is now retired by `other` org; acme should not be able to take it.
    await expect(
      orgService.renameOrganizationSlug(acme.actors.admin, {
        orgId: acme.org.id,
        slug: "other",
      }),
    ).rejects.toBeInstanceOf(InvalidSlugError);
  });

  it("renaming back to a retired slug of its own ends that retirement and retires the replaced one", async () => {
    // acme is currently "acme-renamed", with "acme" retired by itself.
    const result = await orgService.renameOrganizationSlug(acme.actors.admin, {
      orgId: acme.org.id,
      slug: "acme",
    });
    expect(result.slug).toBe("acme");

    // "acme-renamed" should now resolve back to acme (retired), and acme itself should be free for someone else... well can't double check another org without creating one.
    const byOldRetired = await orgRepo.findOrgBySlug("acme-renamed");
    expect(byOldRetired?.id).toBe(acme.org.id);

    // acme should be available to itself trivially (already current) - available check:
    const available = await orgRepo.isSlugAvailableForRename("acme", acme.org.id);
    expect(available).toBe(true);
  });

  it("permission: a viewer cannot rename", async () => {
    const { PermissionDeniedError } = await import("@/lib/permissions");
    await expect(
      orgService.renameOrganizationSlug(acme.actors.viewer, {
        orgId: acme.org.id,
        slug: "acme-by-viewer",
      }),
    ).rejects.toBeInstanceOf(PermissionDeniedError);
  });
});
EOF
